  echo "== $n aerial_cattle g2";  ev --images /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/aerial_cattle/test/images --gt /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/aerial_cattle/test/labels --names /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/evalsets/aerial_cattle_names.txt --classes livestock --grid 2 --min-px 8 --json $R/$n-ac.json
  echo "== $n feedlot g2";  ev --images /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/counting_cattle_t640/test/images --gt /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/counting_cattle_t640/test/labels --names /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/evalsets/counting_cattle_names.txt --classes livestock --grid 2 --min-px 8 --json $R/$n-cc.json
  echo "== $n sheep g2";  ev --images /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/sheep_t640/test/images --gt /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/sheep_t640/test/labels --names /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/evalsets/sheep_names.txt --classes livestock --grid 2 --min-px 8 --json $R/$n-sh.json
  echo "== $n cars-above g1";  ev --images /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/parking/test/images --gt /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/parking/test/labels --names /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/rf/parking/names.txt --classes car --grid 1 --min-px 8 --json $R/$n-pk.json
