  echo "== $n openimages val g1";  ev --images /home/user/uav-silm/onboard/training/datasets/openimages/images/val --gt /home/user/uav-silm/onboard/training/datasets/openimages/labels/val --names /tmp/claude-0/-home-user-uav-silm/f8394c79-738f-5921-8a5f-26e6da42759b/scratchpad/evalsets/oi_names.txt --classes person,car,truck,tractor,livestock --grid 1 --min-px 16 --json $R/$n-oi.json
